class WordIterator {
  constructor(sentence) {
    this.words = sentence.split(" ");
    this.index = 0;
  }

  [Symbol.iterator]() {
    return this;  // the object itself is the iterator
  }

  next() {
    if (this.index < this.words.length) {
      return { value: this.words[this.index++], done: false };
    }
    return { done: true };
  }
}

let words = new WordIterator("Hello World from JavaScript");
for (let word of words) console.log(word);
// "Hello" "World" "from" "JavaScript"

let [first, second, ...rest] = words;
console.log(first, second, rest);

function* countTo(n) {
  for (let i = 1; i <= n; i++) {
    yield i;
  }
}

let gen = countTo(3);
console.log(gen.next());  // { value: 1, done: false }
console.log(gen.next());  // { value: 2, done: false }
console.log(gen.next());  // { value: 3, done: false }
console.log(gen.next());  // { value: undefined, done: true }

// Works with for...of!
for (let num of countTo(5)) {
  console.log(num);  // 1, 2, 3, 4, 5
}

