async function* fetchPages(baseUrl) {
  let page = 1;
  while (true) {
    let response = await fetch(`${baseUrl}?page=${page}`);
    let data = await response.json();
    if (data.length === 0) return;
    yield data;
    page++;
  }
}

// Iterate over all pages
for await (let pageData of fetchPages("/api/posts")) {
  console.log("Page:", pageData.length, "items");
  pageData.forEach(post => console.log(post.title));
}
